/**
 * APAC Reach Radar — the Singapore VPS hero's signature visual.
 *
 * Not a map (that's NetworkMap's job elsewhere) and not a boxed console panel
 * (that's DeployStage/NetworkMap's shared "glass card" language) — this is a
 * radar/sonar sweep, because the pitch for this page IS distance-from-Singapore.
 * Concentric rings are the page's own real region groupings (Southeast Asia,
 * India, East Asia, Australia — straight out of this page's copy), not invented
 * per-city millisecond figures we can't measure or stand behind. A rotating
 * sweep (CSS conic-gradient, transform: rotate) circles the rings continuously;
 * each city node "lights up" as the beam crosses it via a phase-matched
 * negative animation-delay on the same keyframe loop. Pure SVG + CSS, no
 * client JS, deterministic and SSR-safe — floats free on the page (no border,
 * no glass panel) so it reads as ambient environment, not another UI card.
 */

type Ring = { label: string; r: number };
type City = { name: string; angle: number; ringIdx: number };

const RINGS: Ring[] = [
  { label: "Southeast Asia", r: 92 },
  { label: "India", r: 148 },
  { label: "East Asia", r: 204 },
  { label: "Australia", r: 256 },
];

const CITIES: City[] = [
  { name: "Jakarta", angle: 150, ringIdx: 0 },
  { name: "Manila", angle: 44, ringIdx: 0 },
  { name: "Bangkok", angle: 296, ringIdx: 0 },
  { name: "Mumbai", angle: 234, ringIdx: 1 },
  { name: "Hong Kong", angle: 18, ringIdx: 2 },
  { name: "Tokyo", angle: 68, ringIdx: 2 },
  { name: "Sydney", angle: 112, ringIdx: 3 },
];

const CX = 300;
const CY = 300;
const SWEEP_S = 7;

// angle 0 = top (12 o'clock), increasing clockwise — matches the CSS
// conic-gradient's "from 0deg" convention below, so the sweep and the
// per-city flash line up.
const toXY = (angle: number, r: number) => {
  const rad = (angle * Math.PI) / 180;
  return { x: CX + r * Math.sin(rad), y: CY - r * Math.cos(rad) };
};

export function ApacReachRadar() {
  return (
    <div className="select-none">
      <style>{`
        @keyframes radar-spin { to { transform: rotate(360deg); } }
        @keyframes radar-blip { 0%, 100% { opacity: 1; } 10%, 90% { opacity: 0.32; } }
        @media (prefers-reduced-motion: reduce) {
          .radar-sweep { animation: none !important; opacity: 0.25 !important; }
          .radar-blip { animation: none !important; opacity: 0.75 !important; }
        }
      `}</style>
      <div className="relative mx-auto aspect-square w-full max-w-[540px]">
        {/* rotating sweep — sits behind the SVG, shows through its transparent bg */}
        <div
          aria-hidden
          className="radar-sweep absolute inset-0 rounded-full"
          style={{
            background:
              "conic-gradient(from 0deg, rgba(34,211,238,0.55) 0deg, rgba(111,71,245,0.18) 30deg, transparent 75deg, transparent 360deg)",
            WebkitMaskImage: "radial-gradient(circle, black 62%, transparent 78%)",
            maskImage: "radial-gradient(circle, black 62%, transparent 78%)",
            animation: `radar-spin ${SWEEP_S}s linear infinite`,
          }}
        />

        <svg viewBox="0 0 600 600" className="relative block h-full w-full" role="img" aria-label="Singapore at the center of Southeast Asia, India, East Asia and Australia — reach radiating outward by region.">
          <defs>
            <radialGradient id="rr-core" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor="#22d3ee" />
              <stop offset="100%" stopColor="#6f47f5" />
            </radialGradient>
          </defs>

          {/* faint spokes for a console feel */}
          {[0, 45, 90, 135, 180, 225, 270, 315].map((a) => {
            const p = toXY(a, 256);
            return <line key={a} x1={CX} y1={CY} x2={p.x} y2={p.y} stroke="rgba(148,163,184,0.07)" strokeWidth="1" />;
          })}

          {/* rings + labels */}
          {RINGS.map((ring) => (
            <g key={ring.label}>
              <circle cx={CX} cy={CY} r={ring.r} fill="none" stroke="rgba(148,163,184,0.16)" strokeWidth="1" strokeDasharray="2 5" />
              <text x={CX + 6} y={CY - ring.r - 6} fontFamily="var(--font-mono)" fontSize="10.5" letterSpacing="0.06em" fill="rgba(148,163,184,0.55)">
                {ring.label.toUpperCase()}
              </text>
            </g>
          ))}

          {/* Singapore core */}
          <circle cx={CX} cy={CY} r="20" fill="rgba(34,211,238,0.10)" />
          <circle cx={CX} cy={CY} r="7" fill="url(#rr-core)" />
          <text x={CX} y={CY + 40} textAnchor="middle" fontFamily="var(--font-mono)" fontSize="12" fontWeight={600} letterSpacing="0.08em" fill="#e2e8f0">
            SIN
          </text>

          {/* city nodes */}
          {CITIES.map((c, i) => {
            const { x, y } = toXY(c.angle, RINGS[c.ringIdx].r);
            const delay = -((c.angle / 360) * SWEEP_S);
            const labelRight = c.angle > 180;
            return (
              <g key={c.name}>
                <circle
                  className="radar-blip"
                  cx={x}
                  cy={y}
                  r="4"
                  fill="#67e8f9"
                  style={{ animation: `radar-blip ${SWEEP_S}s linear infinite`, animationDelay: `${delay}s` }}
                />
                <circle cx={x} cy={y} r="9" fill="none" stroke="rgba(103,232,249,0.35)" strokeWidth="1" />
                <text
                  x={x + (labelRight ? -10 : 10)}
                  y={y + 3.5}
                  textAnchor={labelRight ? "end" : "start"}
                  fontFamily="var(--font-mono)"
                  fontSize="10.5"
                  fill="#cbd5e1"
                >
                  {c.name}
                </text>
              </g>
            );
          })}
        </svg>
      </div>
      <p className="mt-5 text-center font-mono text-[11px] uppercase tracking-[0.14em] text-slate-500">
        On the region&rsquo;s submarine cable hub &middot; SEA-ME-WE &middot; APG &middot; AAE-1
      </p>
    </div>
  );
}

